440	// options and positionals.
441	//
442	// Parse is exactly ParseWithSources with no config and no environment:
443	// ConfigKey and EnvVar bindings have no effect and the process
444	// environment is never read.
445	func (p *Parser) Parse(args []string) (*Result, error) {
446		return p.ParseWithSources(args, nil, nil)
447	}
448	
449	// ParseWithSources decodes args with two additional explicit value
450	// layers. Precedence is fixed, command line first: a value supplied by a
451	// higher layer replaces the lower layer wholesale for that option —
452	// layers are never concatenated. The order is args, then environ, then
453	// config, then the option's Default.
454	//
455	// config binds by Option.ConfigKey: a key may carry several raw values in
456	// order; a non-repeatable option takes the last one while a repeatable
457	// option retains every value. A present but empty slice counts as not
458	// supplied. environ binds by Option.EnvVar and contributes the single
459	// map value. A present-but-empty environment value or config element is
460	// still an explicit value and is converted according to the option's
461	// type (an empty element therefore fails TypeInt/TypeDuration/TypeBool
462	// conversion). Config keys and environment variables no option binds are
463	// ignored, and the process environment is never read.
464	//
465	// Neither args, config nor environ (nor the slices inside config) is
466	// modified or retained. On failure the error is a *ParseError — a
467	// conversion failure in config or environ wraps ErrInvalidValue with
468	// Name set to the canonical long name, Value to the raw value, Source to
469	// SourceConfig or SourceEnvironment, and Token empty — and the returned
470	// result is nil, with no partial values.
471	func (p *Parser) ParseWithSources(args []string, config map[string][]string, environ map[string]string) (*Result, error) {
472		r := &Result{parser: p}
473		r.layers[0] = make(optionValues)
474		r.values = r.layers[0]
475	
476		onlyPositional := false
477		for i := 0; i < len(args); i++ {
478			token := args[i]
479	
480			if onlyPositional {
481				r.pos = append(r.pos, token)
482				continue
483			}
484			if token == "--" {
485				onlyPositional = true
486				continue
487			}
488	
489			switch {
490			case strings.HasPrefix(token, "--"):
491				if err := p.parseLong(token, args, &i, r); err != nil {
492					return nil, err
493				}
494			case len(token) > 1 && token[0] == '-':
495				if err := p.parseShort(token, args, &i, r); err != nil {
496					return nil, err
497				}
498			default:
499				// A bare "-" is an ordinary positional token.
500				r.pos = append(r.pos, token)
501			}
502		}
503	
504		if err := p.applyEnviron(r, environ); err != nil {
505			return nil, err
506		}
507		if err := p.applyConfig(r, config); err != nil {
508			return nil, err
509		}
510	
511		if err := p.checkRequired(r); err != nil {
512			return nil, err
513		}
514		return r, nil
515	}
516	
517	// record stores one command-line occurrence.
518	func (r *Result) record(opt *compiledOption, value any) {
519		r.values.record(opt, value)
520	}
521	
522	// applyEnviron fills the environment layer for every option absent from
